/**
 * emblem.js
 * -------------------------------------------------------------
 * The Ganesha emblem shown at the top of every biodata, embedded
 * as a data URL (generated from assets/ganesha.jpeg).
 *
 * Why it is embedded instead of loaded from assets/: when the app
 * is opened straight from disk (file://), browsers treat every
 * local image as cross-origin. html2canvas then taints its canvas
 * and the PDF export fails with "Tainted canvases may not be
 * exported". A data URL is always same-origin, so export works
 * both from disk and from a web server.
 *
 * To change the emblem, replace this string with a new data URL.
 * -------------------------------------------------------------
 */
const EMBLEM_DATA_URL = 'data:image/jpeg;base64,';
